// Writes src/api/buildEnv.ts before bundling.
// Metro never sees shell env in Gradle builds (and its cache ignores env),
// so the API URL is baked through this generated file instead. Deterministic.
// Priority: process env first (EAS secrets), then apps/mobile/.env.
const fs = require("fs");
const path = require("path");

const mobileDir = path.resolve(__dirname, "..");
const envPath = path.join(mobileDir, ".env");
const outPath = path.join(mobileDir, "src", "api", "buildEnv.ts");

let url = (process.env.EXPO_PUBLIC_API_URL || "").trim();
if (!url) {
  try {
    const env = fs.readFileSync(envPath, "utf8");
    const m = env.match(/^\s*EXPO_PUBLIC_API_URL\s*=\s*"?([^"\r\n]*)"?\s*$/m);
    if (m) url = m[1].trim();
  } catch (e) {
    console.log("[buildEnv] no .env found, leaving empty");
  }
}

fs.writeFileSync(
  outPath,
  "// AUTO-GENERATED by scripts/write-build-env.js during the Gradle build.\n" +
    "// Do not edit by hand: edit apps/mobile/.env instead.\n" +
    `export const BUILD_API_URL = ${JSON.stringify(url)};\n`
);
console.log("[buildEnv] wrote " + outPath + " -> " + (url || "(empty)"));
